import { db, collection, doc, addDoc, updateDoc, deleteDoc, writeBatch,
         onSnapshot, query, orderBy, serverTimestamp } from './firebase.js';
import { toast, confirmar } from './utils.js';

export let sacolinhas = [];
let unsubSac = null;
let filtroStatusSac = '';
let filtroComSac    = '';
let filtroLiderSac  = '';
let filtroIdadeSac  = '';
let buscaSac        = '';

// IDs selecionados para impressão de etiquetas (persiste entre filtros)
let selecionadasSac = new Set();

export function iniciarListenerSacolinhas() {
  if (unsubSac) return;
  const q = query(collection(db, 'sacolinhas'), orderBy('criadoEm', 'asc'));
  unsubSac = onSnapshot(q, snap => {
    sacolinhas = snap.docs.map(d => ({ id: d.id, ...d.data() }));
    if (window.currentViewIsSacolinhas?.()) window.renderList();
    atualizarBadgeSac();
  }, err => {
    console.error('Erro Firestore (sacolinhas):', err);
  });
}

function atualizarBadgeSac() {
  const pend = sacolinhas.filter(s => s.status !== 'entregue').length;
  const b = document.getElementById('badge-sacolinhas');
  if (b) { b.textContent = pend; b.style.display = pend > 0 ? '' : 'none'; }
}

// Converte idade em texto livre ("9 meses", "1 ano e 2 meses", "RN", "8")
// para número de anos, permitindo filtrar por faixa etária
export function idadeEmAnos(txt) {
  if (txt === null || txt === undefined || txt === '') return null;
  const t = String(txt).toLowerCase().trim();
  if (/rec[eé]m|\brn\b|nascid/.test(t)) return 0;
  const anos = t.match(/(\d+)\s*ano/);
  if (anos) return parseInt(anos[1], 10);
  if (/m[eê]s|meses|dias?\b/.test(t)) return 0;   // meses ou dias = menos de 1 ano
  const num = t.match(/^0*(\d+)/);
  if (num) return parseInt(num[1], 10);
  return null;
}

const FAIXAS_IDADE = [
  { v:'bebe',  rot:'👶 Menos de 1 ano', teste: a => a === 0 },
  { v:'1-3',   rot:'1 a 3 anos',        teste: a => a >= 1  && a <= 3 },
  { v:'4-6',   rot:'4 a 6 anos',        teste: a => a >= 4  && a <= 6 },
  { v:'7-9',   rot:'7 a 9 anos',        teste: a => a >= 7  && a <= 9 },
  { v:'10-12', rot:'10 a 12 anos',      teste: a => a >= 10 && a <= 12 },
  { v:'13+',   rot:'13 anos ou mais',   teste: a => a >= 13 },
  { v:'sem',   rot:'Idade não informada', teste: a => a === null },
];

// Separa "Baraldi- Líder Silmara" em comunidade e líder
// (para registros antigos que ainda têm tudo junto)
export function partesComunidade(s) {
  if (s.lider !== undefined && s.lider !== null) {
    return { com: (s.comunidade||'').trim(), lider: (s.lider||'').trim() };
  }
  const raw = (s.comunidade||'').trim();
  const i = raw.indexOf('-');
  if (i === -1) return { com: raw, lider: '' };
  return {
    com:   raw.slice(0, i).trim(),
    lider: raw.slice(i+1).replace(/l[ií]der/i, '').trim()
  };
}

// ── Render da view (formato lista) ─────────────
window.renderSacolinhas = (el) => {
  const ll = document.getElementById('list-label');

  const todas = [...sacolinhas].sort((a,b)=>(a.numero||0)-(b.numero||0));

  // Opções dos filtros (a partir de todos os registros)
  const comunidades = [...new Set(todas.map(s=>partesComunidade(s).com).filter(Boolean))].sort();
  const lideres     = [...new Set(todas.map(s=>partesComunidade(s).lider).filter(Boolean))].sort();

  // Aplicar filtros
  let list = todas;
  if (filtroStatusSac) list = list.filter(s => (s.status||'aguardando') === filtroStatusSac);
  if (filtroComSac)    list = list.filter(s => partesComunidade(s).com === filtroComSac);
  if (filtroLiderSac)  list = list.filter(s => partesComunidade(s).lider === filtroLiderSac);
  if (filtroIdadeSac) {
    const faixa = FAIXAS_IDADE.find(f => f.v === filtroIdadeSac);
    if (faixa) list = list.filter(s => faixa.teste(idadeEmAnos(s.idade)));
  }
  if (buscaSac) {
    const t = buscaSac.toLowerCase();
    list = list.filter(s =>
      (s.nome||'').toLowerCase().includes(t) ||
      (s.comunidade||'').toLowerCase().includes(t) ||
      String(s.numero||'').includes(t));
  }

  const total     = sacolinhas.length;
  const entregues = sacolinhas.filter(s=>s.status==='entregue').length;
  const aguard    = total - entregues;

  if (ll) ll.textContent = `${list.length} sacolinha${list.length!==1?'s':''}`;

  // guarda os ids atualmente filtrados, usado por "selecionar todos"
  window._sacListIds = list.map(s => s.id);

  el.innerHTML = `
    <div class="sac-wrap">
      <div class="sac-header">
        <div class="sac-stats">
          <div class="sac-stat"><span class="sac-val">${total}</span><span class="sac-lbl">Total</span></div>
          <div class="sac-stat sac-stat-ag"><span class="sac-val">${aguard}</span><span class="sac-lbl">Aguardando</span></div>
          <div class="sac-stat sac-stat-ok"><span class="sac-val">${entregues}</span><span class="sac-lbl">Entregues</span></div>
        </div>
        <div class="sac-actions">
          <button class="btn btn-am" onclick="window.abrirModalSacolinha()">
            <i class="ti ti-plus"></i> Nova sacolinha
          </button>
          <button class="btn" onclick="window.importarSacolinhas()" title="Importar/corrigir lista oficial">
            <i class="ti ti-database-import"></i> Importar lista
          </button>
          ${total ? `<button class="btn btn-verde" onclick="window.fichasTodasPDF()">
            <i class="ti ti-file-type-pdf"></i> Imprimir etiquetas${selecionadasSac.size ? ` (${selecionadasSac.size} selecionada${selecionadasSac.size!==1?'s':''})` : ''}
          </button>
          <button class="btn" onclick="window.exportarPlanilhaSacolinhas()" title="Exportar para Excel">
            <i class="ti ti-file-spreadsheet"></i> Exportar planilha
          </button>
          ${selecionadasSac.size ? `<button class="btn btn-red" onclick="window.excluirSelecionadasSac()">
            <i class="ti ti-trash"></i> Excluir selecionadas (${selecionadasSac.size})
          </button>` : ''}` : ''}
        </div>
      </div>

      <div class="sac-filtros">
        <input class="fi" style="flex:2;min-width:150px" placeholder="🔍 Buscar por nome, comunidade ou nº…"
               value="${buscaSac.replace(/"/g,'&quot;')}"
               oninput="window.buscarSacolinha(this.value)">
        <select class="fi" style="flex:1;min-width:130px" onchange="window.filtrarComunidade(this.value)">
          <option value="">📍 Todas as comunidades</option>
          ${comunidades.map(c=>`<option value="${c.replace(/"/g,'&quot;')}" ${filtroComSac===c?'selected':''}>${c}</option>`).join('')}
        </select>
        <select class="fi" style="flex:1;min-width:120px" onchange="window.filtrarLider(this.value)">
          <option value="">👤 Todos os líderes</option>
          ${lideres.map(l=>`<option value="${l.replace(/"/g,'&quot;')}" ${filtroLiderSac===l?'selected':''}>${l}</option>`).join('')}
        </select>
        <select class="fi" style="flex:1;min-width:120px" onchange="window.filtrarIdade(this.value)">
          <option value="">🎂 Todas as idades</option>
          ${FAIXAS_IDADE.map(f=>{
            const qtd = todas.filter(s=>f.teste(idadeEmAnos(s.idade))).length;
            return qtd ? `<option value="${f.v}" ${filtroIdadeSac===f.v?'selected':''}>${f.rot} (${qtd})</option>` : '';
          }).join('')}
        </select>
        <select class="fi" style="max-width:140px" onchange="window.filtrarSacolinha(this.value)">
          <option value=""            ${filtroStatusSac===''           ?'selected':''}>Todas</option>
          <option value="aguardando"  ${filtroStatusSac==='aguardando' ?'selected':''}>🎁 Aguardando</option>
          <option value="entregue"    ${filtroStatusSac==='entregue'   ?'selected':''}>✅ Entregues</option>
        </select>
        ${(filtroComSac||filtroLiderSac||filtroStatusSac||filtroIdadeSac||buscaSac) ? `
        <button class="btn btn-sm" onclick="window.limparFiltrosSac()" title="Limpar filtros">
          <i class="ti ti-filter-off"></i>
        </button>` : ''}
        ${selecionadasSac.size ? `
        <button class="btn btn-sm" onclick="window.limparSelecaoSac()" title="Limpar seleção">
          <i class="ti ti-square-off"></i> Limpar seleção (${selecionadasSac.size})
        </button>` : ''}
      </div>

      ${!list.length ? `
        <div class="empty-state">
          <i class="ti ti-gift-off"></i><br>Nenhuma sacolinha ${total ? 'encontrada com esses filtros' : 'cadastrada'}.<br>
          <button class="btn btn-am" style="margin-top:12px" onclick="window.abrirModalSacolinha()">
            <i class="ti ti-plus"></i> Cadastrar primeira sacolinha
          </button>
        </div>` : `
        <div class="sac-table-wrap">
          <table class="sac-table">
            <thead><tr>
              <th style="width:56px"><input type="checkbox" title="Selecionar todos os filtrados"
                    ${list.length && list.every(s=>selecionadasSac.has(s.id)) ? 'checked' : ''}
                    onchange="window.selecionarTodosSac(this.checked)"> Nr</th>
              <th>Comunidade</th><th>Líder</th><th>Nome da criança</th>
              <th>Sexo</th><th>Idade</th><th>Nr Roupa</th><th>Nr Calçado</th>
              <th>Nec. especial</th><th>Status</th><th>Ações</th>
            </tr></thead>
            <tbody>
              ${list.map(s => linhaSacolinha(s)).join('')}
            </tbody>
          </table>
        </div>`}
    </div>`;
};

function linhaSacolinha(s) {
  const entregue = s.status === 'entregue';
  const p = partesComunidade(s);
  const sexoTxt = s.sexo === 'FEMININO' ? '👧 F' : s.sexo === 'MASCULINO' ? '👦 M' : '—';
  const sel = selecionadasSac.has(s.id);
  return `
  <tr class="${entregue?'sac-tr-ok':''}${sel?' sac-tr-sel':''}"
      onclick="if(!event.target.closest('button')&&!event.target.closest('a')){window.toggleSelecaoSac('${s.id}')}">
    <td onclick="event.stopPropagation()"><input type="checkbox" class="sac-chk" ${sel?'checked':''}
          onchange="window.selecionarSacolinha('${s.id}', this.checked)">
      <span class="sac-td-num">${s.numero||'—'}</span></td>
    <td>${p.com||'—'}</td>
    <td>${p.lider||'—'}</td>
    <td class="sac-td-nome">${s.nome||'—'}</td>
    <td>${sexoTxt}</td>
    <td>${s.idade!==''&&s.idade!=null?s.idade:'—'}</td>
    <td>${s.roupa||'—'}</td>
    <td>${s.calcado||'—'}</td>
    <td>${s.necesp||'—'}</td>
    <td><span class="tag ${entregue?'tag-ok':'tag-ag'}">${entregue?'✅ Entregue':'🎁 Aguard.'}</span></td>
    <td class="sac-td-acoes">
      <button class="btn btn-xs" onclick="window.fichaSacolinhaPDF('${s.id}')" title="Gerar etiqueta (A4)">
        <i class="ti ti-file-type-pdf"></i>
      </button>
      ${!entregue ? `
      <button class="btn btn-gn btn-xs" onclick="window.marcarEntregueSacolinha('${s.id}')" title="Marcar entregue">
        <i class="ti ti-check"></i>
      </button>` : `
      <button class="btn btn-xs" onclick="window.desfazerEntregaSacolinha('${s.id}')" title="Desfazer entrega">
        <i class="ti ti-arrow-back-up"></i>
      </button>`}
      <button class="btn btn-xs" onclick="window.abrirModalSacolinha('${s.id}')" title="Editar">
        <i class="ti ti-edit"></i>
      </button>
      <button class="btn btn-red btn-xs" onclick="window.excluirSacolinha('${s.id}')" title="Excluir">
        <i class="ti ti-trash"></i>
      </button>
    </td>
  </tr>`;
}

window.buscarSacolinha    = v => { buscaSac = v; refresh(); };
window.filtrarSacolinha   = v => { filtroStatusSac = v; refresh(); };
window.filtrarComunidade  = v => { filtroComSac = v; refresh(); };
window.filtrarLider       = v => { filtroLiderSac = v; refresh(); };
window.filtrarIdade       = v => { filtroIdadeSac = v; refresh(); };
window.limparFiltrosSac   = () => { buscaSac=''; filtroStatusSac=''; filtroComSac=''; filtroLiderSac=''; filtroIdadeSac=''; refresh(); };

// ── Seleção de sacolinhas para impressão de etiquetas ──
window.selecionarSacolinha = (id, marcado) => {
  if (marcado) selecionadasSac.add(id);
  else selecionadasSac.delete(id);
  refresh();
};

window.toggleSelecaoSac = (id) => {
  if (selecionadasSac.has(id)) selecionadasSac.delete(id);
  else selecionadasSac.add(id);
  refresh();
};

window.selecionarTodosSac = (marcado) => {
  const ids = window._sacListIds || [];
  if (marcado) ids.forEach(id => selecionadasSac.add(id));
  else ids.forEach(id => selecionadasSac.delete(id));
  refresh();
};

window.limparSelecaoSac = () => { selecionadasSac.clear(); refresh(); };

function refresh() {
  const el = document.getElementById('family-list');
  if (el) window.renderSacolinhas(el);
}

// ── Foto da criança (upload + compressão) ──────
function comprimirImagem(file, maxLado = 480, qualidade = 0.75) {
  return new Promise((resolve, reject) => {
    const leitor = new FileReader();
    leitor.onload = e => {
      const img = new Image();
      img.onload = () => {
        let { width, height } = img;
        if (width > height && width > maxLado) {
          height = Math.round(height * (maxLado / width));
          width = maxLado;
        } else if (height >= width && height > maxLado) {
          width = Math.round(width * (maxLado / height));
          height = maxLado;
        }
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', qualidade));
      };
      img.onerror = reject;
      img.src = e.target.result;
    };
    leitor.onerror = reject;
    leitor.readAsDataURL(file);
  });
}

window.selecionarFotoSac = async input => {
  const file = input.files?.[0];
  if (!file) return;
  if (!file.type.startsWith('image/')) { toast('⚠️ Selecione um arquivo de imagem.'); return; }
  try {
    const dataUrl = await comprimirImagem(file);
    document.getElementById('sac-foto').value = dataUrl;
    const prev = document.getElementById('sac-foto-preview');
    const icon = document.getElementById('sac-foto-icon');
    prev.src = dataUrl;
    prev.style.display = 'block';
    if (icon) icon.style.display = 'none';
    document.getElementById('sac-foto-remover').style.display = '';
  } catch (e) {
    console.error(e);
    toast('❌ Erro ao processar a foto.');
  }
  input.value = '';
};

window.removerFotoSac = () => {
  document.getElementById('sac-foto').value = '';
  const prev = document.getElementById('sac-foto-preview');
  const icon = document.getElementById('sac-foto-icon');
  prev.src = '';
  prev.style.display = 'none';
  if (icon) icon.style.display = '';
  document.getElementById('sac-foto-remover').style.display = 'none';
};

// ── Modal cadastro/edição ──────────────────────
window.abrirModalSacolinha = (id=null) => {
  const s = id ? sacolinhas.find(x => x.id === id) : null;
  const g = i => document.getElementById(i);
  const ultima = sacolinhas[sacolinhas.length-1];

  const proxNum = sacolinhas.reduce((m,x)=>Math.max(m, Number(x.numero)||0), 0) + 1;

  const pS = s ? partesComunidade(s) : null;
  const pU = ultima ? partesComunidade(ultima) : null;
  g('sac-id').value        = s?.id || '';
  g('sac-numero').value    = s?.numero ?? proxNum;
  g('sac-comunidade').value= pS ? pS.com : (pU?.com || '');
  g('sac-lider').value     = pS ? pS.lider : (pU?.lider || '');
  g('sac-nome').value      = s?.nome || '';
  g('sac-sexo').value      = s?.sexo || '';
  g('sac-idade').value     = s?.idade ?? '';
  g('sac-roupa').value     = s?.roupa || '';
  g('sac-calcado').value   = s?.calcado || '';
  g('sac-necesp').value    = s?.necesp ?? 'Não';
  g('sac-entrega').value   = s?.entrega ?? (ultima?.entrega || '');

  // Foto da criança
  g('sac-foto').value = s?.foto || '';
  const prev = document.getElementById('sac-foto-preview');
  const icon = document.getElementById('sac-foto-icon');
  const btnRemover = document.getElementById('sac-foto-remover');
  if (s?.foto) {
    prev.src = s.foto;
    prev.style.display = 'block';
    if (icon) icon.style.display = 'none';
    if (btnRemover) btnRemover.style.display = '';
  } else {
    prev.src = '';
    prev.style.display = 'none';
    if (icon) icon.style.display = '';
    if (btnRemover) btnRemover.style.display = 'none';
  }

  // Sugestões de comunidades e líderes já cadastrados
  const coms = [...new Set(sacolinhas.map(x=>partesComunidade(x).com).filter(Boolean))].sort();
  const lids = [...new Set(sacolinhas.map(x=>partesComunidade(x).lider).filter(Boolean))].sort();
  const dc = document.getElementById('lista-comunidades');
  const dl = document.getElementById('lista-lideres');
  if (dc) dc.innerHTML = coms.map(c=>`<option value="${c.replace(/"/g,'&quot;')}"></option>`).join('');
  if (dl) dl.innerHTML = lids.map(l=>`<option value="${l.replace(/"/g,'&quot;')}"></option>`).join('');

  document.getElementById('modal-sacolinha-titulo').textContent =
    s ? 'Editar sacolinha' : 'Cadastrar nova sacolinha';
  document.getElementById('modal-sacolinha').style.display = 'flex';
  setTimeout(() => g('sac-nome').focus(), 100);
};

window.salvarSacolinha = async () => {
  const g = i => document.getElementById(i).value.trim();
  const id   = document.getElementById('sac-id').value;
  const nome = g('sac-nome');
  const numero = Number(g('sac-numero'));
  if (!nome)   { toast('⚠️ Informe o nome da criança'); return; }
  if (!numero) { toast('⚠️ Informe o número do cadastro'); return; }

  const dados = {
    numero,
    comunidade: g('sac-comunidade'),
    lider:      g('sac-lider'),
    nome,
    sexo:       g('sac-sexo'),
    idade:      g('sac-idade'),
    roupa:      g('sac-roupa'),
    calcado:    g('sac-calcado'),
    necesp:     g('sac-necesp') || 'Não',
    entrega:    g('sac-entrega'),
    foto:       document.getElementById('sac-foto').value || '',
  };

  try {
    if (id) {
      await updateDoc(doc(db,'sacolinhas',id), dados);
      toast('✅ Sacolinha atualizada!');
    } else {
      await addDoc(collection(db,'sacolinhas'), {
        ...dados,
        status: 'aguardando',
        criadoEm: serverTimestamp()
      });
      toast('🎁 Sacolinha cadastrada!');
    }
    window.fecharModal('modal-sacolinha');
  } catch(e) {
    console.error(e);
    toast('❌ Erro ao salvar. Tente novamente.');
  }
};

window.marcarEntregueSacolinha = async id => {
  try {
    await updateDoc(doc(db,'sacolinhas',id), {
      status:'entregue',
      entregueEm: serverTimestamp()
    });
    toast('✅ Sacolinha marcada como entregue!');
  } catch(e){ toast('❌ Erro ao atualizar.'); }
};

window.desfazerEntregaSacolinha = async id => {
  try {
    await updateDoc(doc(db,'sacolinhas',id), { status:'aguardando' });
    toast('↩️ Entrega desfeita.');
  } catch(e){ toast('❌ Erro ao atualizar.'); }
};

window.excluirSacolinha = async id => {
  const s = sacolinhas.find(x=>x.id===id);
  const ok = await confirmar(`Excluir a sacolinha de "${s?.nome||''}"? Esta ação não pode ser desfeita.`);
  if (!ok) return;
  try {
    await deleteDoc(doc(db,'sacolinhas',id));
    toast('🗑️ Sacolinha excluída.');
  } catch(e){ toast('❌ Erro ao excluir.'); }
};

// ── Exclusão em lote das sacolinhas selecionadas ────
window.excluirSelecionadasSac = async () => {
  const ids = [...selecionadasSac];
  if (!ids.length) { toast('Nenhuma sacolinha selecionada.'); return; }
  const ok = await confirmar(`Excluir ${ids.length} sacolinha${ids.length!==1?'s':''} selecionada${ids.length!==1?'s':''}? Esta ação não pode ser desfeita.`);
  if (!ok) return;
  try {
    // Firestore permite no máximo 500 operações por batch
    const LOTE = 450;
    for (let i = 0; i < ids.length; i += LOTE) {
      const fatia = ids.slice(i, i + LOTE);
      const batch = writeBatch(db);
      fatia.forEach(id => batch.delete(doc(db,'sacolinhas',id)));
      await batch.commit();
    }
    selecionadasSac.clear();
    toast(`🗑️ ${ids.length} sacolinha${ids.length!==1?'s':''} excluída${ids.length!==1?'s':''}!`);
  } catch(e) {
    console.error(e);
    toast('❌ Erro ao excluir em lote.');
  }
};

// ══════════════════════════════════════════════
//  ETIQUETA — meia folha A4 (2 por página)
//  Arte oficial embutida: nenhum arquivo externo
// ══════════════════════════════════════════════
const ART_LOGO   = 'data:image/png;base64,';
const ART_SANTA  = 'data:image/png;base64,';
const ART_RODAPE = 'data:image/png;base64,';
const LOGO_FB    = 'data:image/png;base64,';
const LOGO_IG    = 'data:image/png;base64,';

const MEIA_H = 148.5; // altura de meia folha A4

// Desenha uma etiqueta completa dentro da metade da página (oy = deslocamento vertical)
function desenharEtiquetaMeia(pdf, s, oy) {
  const W = 210;
  const vermelho = [220, 30, 30];
  const preto    = [20, 20, 20];
  const Y = v => oy + v;

  // Moldura
  pdf.setDrawColor(...preto);
  pdf.setLineWidth(0.5);
  pdf.rect(4, Y(3), W - 8, MEIA_H - 6);

  // Logo SUPER AMIGOS
  pdf.addImage(ART_LOGO, 'PNG', 78, Y(5), 54, 13);

  // Papai Noel — bem grande, ocupa todo o canto superior direito
  pdf.addImage(ART_SANTA, 'PNG', 134, Y(6), 68, 45.7);

  // Título
  pdf.setTextColor(...vermelho);
  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(10.5);
  pdf.text('AÇÃO ESPECIAL DE NATAL SUPERAMIGOS', 88, Y(23), { align: 'center' });

  // Cadastro NR
  pdf.setTextColor(...preto);
  pdf.setFont('helvetica', 'normal');
  pdf.setFontSize(8.5);
  pdf.text('CADASTRO NR', 62, Y(29), { align: 'center' });
  pdf.setLineWidth(0.4);
  pdf.rect(46, Y(30.5), 32, 8);
  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(12);
  pdf.text(String(s.numero || ''), 62, Y(36.3), { align: 'center' });

  // Campos (rótulo em negrito + valor; encolhe a fonte se não couber)
  const campo = (rotulo, valor, x, y, larguraMax, tr = 9.5, tv = 10) => {
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(tr);
    pdf.text(rotulo, x, Y(y));
    const w = pdf.getTextWidth(rotulo + ' ');
    const txt = String(valor ?? '');
    let tam = tv;
    if (larguraMax) {
      const disp = larguraMax - w;
      pdf.setFontSize(tam);
      while (tam > 6 && pdf.getTextWidth(txt) > disp) {
        tam -= 0.3;
        pdf.setFontSize(tam);
      }
    }
    pdf.setFontSize(tam);
    pdf.text(txt, x + w + 1, Y(y));
  };

  // Comunidade e Líder — campos separados
  campo('COMUNIDADE:', s.comunidade, 10, 45, 76);
  campo('LÍDER:', s.lider, 88, 45, 46);

  campo('NOME:', s.nome, 10, 53, 124, 10, 10.5);
  campo('SEXO:', s.sexo, 10, 61, 76);
  campo('IDADE:', s.idade, 88, 61, 38);
  campo('NR ROUPA:', s.roupa, 10, 69, 76);
  campo('NR CALÇADO:', s.calcado, 88, 69, 38);
  campo('NECESSIDADE ESPECIAL:', s.necesp || 'Não', 10, 77, 116);

  // Espaço para a foto da criança (maior ainda, mais para baixo e mais à esquerda)
  const fx = 128, fy = Y(56), fw = 72, fh = 56;
  if (s.foto) {
    try { pdf.addImage(s.foto, 'JPEG', fx, fy, fw, fh); } catch (e) { console.warn('foto inválida', e); }
    pdf.setDrawColor(...preto);
    pdf.setLineWidth(0.4);
    pdf.rect(fx, fy, fw, fh);
  } else {
    pdf.setFillColor(252, 252, 252);
    pdf.setDrawColor(130, 130, 130);
    pdf.setLineWidth(0.4);
    pdf.setLineDashPattern([1.4, 1.1], 0);
    pdf.rect(fx, fy, fw, fh, 'FD');
    pdf.setLineDashPattern([], 0);
    pdf.setTextColor(150, 150, 150);
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(9);
    pdf.text('FOTO DA', fx + fw / 2, fy + fh / 2 - 2, { align: 'center' });
    pdf.text('CRIANÇA', fx + fw / 2, fy + fh / 2 + 4, { align: 'center' });
  }

  // Faixa "INFORMAÇÕES IMPORTANTES" com Leitão e Ursinho (encolhida para não invadir a foto)
  pdf.addImage(ART_RODAPE, 'PNG', 56, Y(83), 70, 22.4);

  // Instruções
  pdf.setTextColor(...preto);
  const escreverMisto = (partes, x, yy, maxW) => {
    let cx = x;
    pdf.setFontSize(7.8);
    partes.forEach(([t, st]) => {
      pdf.setFont('helvetica', st === 'b' ? 'bold' : st === 'bi' ? 'bolditalic' : st === 'i' ? 'italic' : 'normal');
      t.split(' ').forEach(p => {
        const w = pdf.getTextWidth(p + ' ');
        if (cx + w > x + maxW) { cx = x; yy += 4.2; }
        pdf.text(p, cx, Y(yy));
        cx += w;
      });
    });
    return yy;
  };

  escreverMisto([
    ['COLOCAR NA SACOLINHA:', 'bi'],
    ['ROUPA:', 'b'], ['camiseta / blusa / calça / shorts / cueca ou calcinha e meia.', 'n'],
    ['SAPATO:', 'bi'], ['tenis ou sandália - chinelo opcional;', 'i'],
    ['HIGIENE PESSOAL:', 'bi'], ['sabonete, shampoo, pasta e escova de dente;', 'i'],
    ['BRINQUEDO:', 'b'], ['conforme idade e sexo da criança;', 'n'],
  ], 9, 118, 192);

  // Avisos finais
  pdf.setTextColor(...vermelho);
  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(11);
  pdf.text('TODOS OS ITENS DEVERÃO ESTAR EMBRULHADOS', W / 2, Y(131), { align: 'center' });

  pdf.setTextColor(...preto);
  pdf.setFont('helvetica', 'bolditalic');
  pdf.setFontSize(10);
  pdf.text(`ENTREGAR A SACOLINHA ATÉ O DIA ${s.entrega || '___/___/____'}`, W / 2, Y(137), { align: 'center' });

  // Rodapé redes sociais
  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(8);
  pdf.setTextColor(...preto);
  pdf.setDrawColor(...preto);
  pdf.setLineWidth(0.3);
  pdf.line(4, Y(139), W - 4, Y(139));
  pdf.addImage(LOGO_FB, 'PNG', 30, Y(140.2), 4.6, 4.6);
  pdf.text('SUPERAMIGOSANOS', 36, Y(143.4));
  pdf.addImage(LOGO_IG, 'PNG', 118, Y(140.2), 4.6, 4.6);
  pdf.text('SUPERAMIGOSSCANIA', 124, Y(143.4));
}

// Linha de corte entre as duas etiquetas
function linhaCorte(pdf) {
  pdf.setDrawColor(160, 160, 160);
  pdf.setLineWidth(0.3);
  pdf.setLineDashPattern([2, 2], 0);
  pdf.line(0, MEIA_H, 210, MEIA_H);
  pdf.setLineDashPattern([], 0);
  pdf.setTextColor(150, 150, 150);
  pdf.setFont('helvetica', 'normal');
  pdf.setFontSize(6);
  pdf.text('✂ recortar aqui', 105, MEIA_H - 1, { align: 'center' });
}

window.fichaSacolinhaPDF = id => {
  const s = sacolinhas.find(x => x.id === id);
  if (!s) return;
  if (!window.jspdf) { toast('⚠️ Recarregue a página e tente novamente'); return; }
  const { jsPDF } = window.jspdf;
  const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
  desenharEtiquetaMeia(pdf, s, 0);
  linhaCorte(pdf);
  pdf.save(`etiqueta_${s.numero || ''}_${(s.nome || '').replace(/\s+/g, '_')}.pdf`);
  toast('🏷️ Etiqueta gerada!');
};

window.fichasTodasPDF = () => {
  if (!window.jspdf) { toast('⚠️ Recarregue a página e tente novamente'); return; }

  // Prioridade: se houver sacolinhas marcadas via checkbox, imprime só essas.
  // Caso contrário, mantém o comportamento anterior (pendentes, ou todas se não houver pendentes).
  let alvo;
  if (selecionadasSac.size) {
    alvo = sacolinhas.filter(s => selecionadasSac.has(s.id));
  } else {
    const pendentes = sacolinhas.filter(s => s.status !== 'entregue');
    alvo = pendentes.length ? pendentes : sacolinhas;
  }
  if (!alvo.length) { toast('Nenhuma sacolinha para imprimir.'); return; }

  const { jsPDF } = window.jspdf;
  const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
  const ordenadas = [...alvo].sort((a, b) => (a.numero || 0) - (b.numero || 0));

  ordenadas.forEach((s, i) => {
    const pos = i % 2;           // 0 = metade de cima, 1 = metade de baixo
    if (i > 0 && pos === 0) pdf.addPage();
    desenharEtiquetaMeia(pdf, s, pos * MEIA_H);
    if (pos === 0) linhaCorte(pdf);
  });

  pdf.save(`etiquetas_sacolinhas_${new Date().toISOString().slice(0, 10)}.pdf`);
  toast(`🏷️ ${ordenadas.length} etiqueta${ordenadas.length !== 1 ? 's' : ''} gerada${ordenadas.length !== 1 ? 's' : ''}!`);
};

window.etiquetaSacolinhaPDF = id => window.fichaSacolinhaPDF(id);
window.etiquetasTodasPDF    = () => window.fichasTodasPDF();

// ══════════════════════════════════════════════
//  EXPORTAR PLANILHA (mesmas colunas do controle)
// ══════════════════════════════════════════════
window.exportarPlanilhaSacolinhas = () => {
  if (!sacolinhas.length) { toast('Nenhuma sacolinha para exportar.'); return; }

  const ordenadas = [...sacolinhas].sort((a,b)=>(a.numero||0)-(b.numero||0));
  const linhas = [
    ['NR CADASTRO','Comunidade','Líder','NOME DA CRIANÇA','SEXO','IDADE',
     'NR ROUPA','NR CALÇADO','NECESSIDADE ESPECIAL','STATUS'],
    ...ordenadas.map(s => {
      const p = partesComunidade(s);
      return [
        s.numero || '', p.com, p.lider, s.nome || '', s.sexo || '',
        s.idade || '', s.roupa || '', s.calcado || '', s.necesp || '',
        s.status === 'entregue' ? 'Entregue' : 'Aguardando'
      ];
    })
  ];

  // Ponto-e-vírgula: separador padrão do Excel em português (BR)
  const csv = linhas
    .map(l => l.map(v => `"${String(v ?? '').replace(/"/g,'""')}"`).join(';'))
    .join('\r\n');
  const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8' });
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement('a');
  a.href = url;
  a.download = `sacolinhas_${new Date().toISOString().slice(0,10)}.csv`;
  a.click();
  URL.revokeObjectURL(url);
  toast(`📊 Planilha com ${ordenadas.length} sacolinhas exportada!`);
};
